with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1pe01ps904u', 'practice', 'Écriture A1 : fiche d''hôtel', 'A1', array['Production écrite']::text[], 'practice', null, null, '<p>Lisez le texte. Vous remplissez la fiche de l''hôtel pour cette personne.</p>', '<p>Bonjour ! Je m''appelle Lan Nguyen. Nguyen, c''est mon nom de famille.</p><p>Je suis née le 12 mars 2004 à Hanoï. Je suis vietnamienne et je suis étudiante.</p><p>J''habite 8, rue de la Paix, à Lyon. Mon numéro de téléphone est le 04 65 71 30 41.</p><p>Je veux rester à l''hôtel 2 nuits.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• le nom de famille (expression) : họ\n• le prénom (nom masculin) : tên\n• la date de naissance (expression) : ngày sinh\n• le lieu de naissance (expression) : nơi sinh\n• une nuit (nom féminin) : đêm","explications":"• Nom là họ, prénom là tên: người Việt rất hay nhầm hai ô này.\n• Ngày viết theo thứ tự ngày, tháng, năm.","kyNang":"A1-PE-1","vong":"hoc","thuTu":1}'::jsonb, '2026-11-01T13:00:00.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxp8ps8000', 'a1pe01ps904u', 1, 'fill', 'Nom : ______', '{}'::jsonb, '{"accepted":"Nguyen"}'::jsonb, '« Nguyen, c''est mon nom de famille ». Nom là họ, prénom là tên.'), ('qmvxp8ps8001', 'a1pe01ps904u', 2, 'fill', 'Prénom : ______', '{}'::jsonb, '{"accepted":"Lan"}'::jsonb, 'Nom là họ, prénom là tên.'), ('qmvxp8ps8002', 'a1pe01ps904u', 3, 'fill', 'Date de naissance (jour/mois/année) : ______', '{}'::jsonb, '{"accepted":"12 mars 2004|12/03/2004|12/3/2004|12-03-2004"}'::jsonb, 'Tiếng Pháp viết ngày trước, tháng sau, năm cuối.'), ('qmvxp8ps8003', 'a1pe01ps904u', 4, 'fill', 'Lieu de naissance : ______', '{}'::jsonb, '{"accepted":"Hanoï|Hanoi"}'::jsonb, '« 