with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1pe02pse04v', 'practice', 'Écriture A1 : inscription au cours', 'A1', array['Production écrite']::text[], 'practice', null, null, '<p>Lisez le texte. Vous remplissez la fiche d''inscription pour cette personne.</p>', '<p>Bonjour, je m''appelle Carlos Mendez. J''ai 30 ans et je suis mexicain. Je suis cuisinier dans un restaurant.</p><p>J''habite 21, avenue Victor-Hugo, à Toulouse. Mon courriel est carlos.mendez@mail.example.</p><p>Je parle espagnol et anglais. Je veux apprendre le français. Je suis libre le mardi soir.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une inscription (nom féminin) : đăng ký\n• une profession (nom féminin) : nghề nghiệp\n• un cuisinier (nom masculin) : đầu bếp\n• un courriel (nom masculin) : email\n• une langue (nom féminin) : ngôn ngữ","explications":"• Trước nghề nghiệp không có mạo từ: Je suis cuisinier.\n• Quốc tịch viết chữ thường khi là tính từ: mexicain.","kyNang":"A1-PE-1","vong":"hoc","thuTu":2}'::jsonb, '2026-11-01T13:00:01.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxp8ps800a', 'a1pe02pse04v', 1, 'fill', 'Nom : ______', '{}'::jsonb, '{"accepted":"Mendez"}'::jsonb, 'Nom là họ, prénom là tên.'), ('qmvxp8ps800b', 'a1pe02pse04v', 2, 'fill', 'Prénom : ______', '{}'::jsonb, '{"accepted":"Carlos"}'::jsonb, 'Nom là họ, prénom là tên.'), ('qmvxp8ps800c', 'a1pe02pse04v', 3, 'fill', 'Âge : ______', '{}'::jsonb, '{"accepted":"30 ans|30|trente ans"}'::jsonb, '« J''ai 30 ans »: tuổi dùng avoir.'), ('qmvxp8ps800d', 'a1pe02pse04v', 4, 'fill', 'Nationalité : ______', '{}'::jsonb, '{"accepted":"mexicain"}'::jsonb, '« je suis mexicain ».'), ('qmvxp8ps800e', 'a1pe02pse04v', 5, 'fill', 'Profession : 