with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1pe05psf04y', 'practice', 'Écriture A1 : remplissez la fiche', 'A1', array['Production écrite']::text[], 'practice', null, null, '<p>Vous travaillez à l''accueil d''une école de français. Hoang vous donne ces informations. Remplissez sa fiche.</p>', '<p>Je m''appelle Hoang Duc Anh. Hoang, c''est mon nom. Je suis vietnamien. Je suis né le 25 janvier 1995 à Hué.</p><p>Je suis ingénieur. J''habite 17, rue Pasteur, à Nantes, avec ma femme. Nous avons un fils.</p><p>Je parle vietnamien et anglais. Je veux un cours le soir.</p><p>Mon téléphone : 02 61 91 73 26.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• l''accueil (nom masculin) : quầy tiếp đón\n• un ingénieur (nom masculin) : kỹ sư\n• une femme (nom féminin) : vợ, phụ nữ\n• un fils (nom masculin) : con trai\n• souhaité, souhaitée (adjectif) : mong muốn","explications":"• Đề thi có 10 ô: làm đủ, ô nào chưa chắc cũng điền.\n• Khi thi thật bạn điền thông tin của chính mình, nên hãy thuộc cách viết họ, tên, ngày sinh và địa chỉ.","isPremium":true,"price":19000,"kyNang":"A1-PE-1","vong":"chot","thuTu":5}'::jsonb, '2026-11-01T13:00:04.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxp8ps8014', 'a1pe05psf04y', 1, 'fill', 'Nom : ______', '{}'::jsonb, '{"accepted":"Hoang"}'::jsonb, '« Hoang, c''est mon nom ».'), ('qmvxp8ps8015', 'a1pe05psf04y', 2, 'fill', 'Prénom : ______', '{}'::jsonb, '{"accepted":"Duc Anh"}'::jsonb, 'Nom là họ, prénom là tên.'), ('qmvxp8ps8016', 'a1pe05psf04y', 3, 'fill', 'Date de naissance : ______', '{}'::jsonb, '{"accepted":"25 janvier 1995|25/01/1995|25/1/1995|25-01-1995"}'::jsonb, 'Ngày, tháng, năm.'), ('qmvxp8ps8017', 'a1pe05psf04y', 4, 'fill', 'Lieu de nai