with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1pe06psf04z', 'practice', 'Écriture A1 : je me présente', 'A1', array['Production écrite']::text[], 'practice', null, null, '<p>Vous arrivez dans une classe de français. Présentez-vous.</p><p>Écrivez votre nom, votre âge, votre ville et votre profession. (30 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• je m''appelle (expression) : tôi tên là\n• j''ai… ans (expression) : tôi… tuổi\n• j''habite à (expression) : tôi sống ở\n• je suis (expression) : tôi là\n• un peu (expression) : một chút","explications":"• Viết theo khung: Je m''appelle, J''ai, J''habite, Je suis.\n• Tuổi dùng avoir: J''ai 20 ans, không viết Je suis 20 ans.","kyNang":"A1-PE-2","vong":"hoc","thuTu":1}'::jsonb, '2026-11-01T13:00:05.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxp8ps801e', 'a1pe06psf04z', 1, 'open', 'Écrivez votre présentation.', '{}'::jsonb, '{"model":"Bonjour ! Je m''appelle Lan et j''ai vingt-deux ans. Je suis vietnamienne. J''habite à Lyon avec une amie. Je suis étudiante à l''université et je parle vietnamien, anglais et un peu français. J''aime beaucoup la France."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1pe07psf050', 'practice', 'Écriture A1 : ma famille', 'A1', array['Production écrite']::text[], 'practice', null, null, '<p>Écrivez un petit texte sur votre famille.</p><p>Parlez de deux personnes : leur âge et leur profession. (30 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• mon père (expression) : bố tôi\n• ma mère (expression) : mẹ tôi\n• mon frère (expression) : anh, em trai tôi\n• ma sœur (expression) : chị, em gái tôi\n• nous sommes quatre (expression) : nhà có bốn người","explications":"• Mon đi với từ giống đực, ma đi với từ giống cái, mes đi với số nhiều.\n• Nói về người khác thì đổi động từ: il a, elle est.","kyNang":"A1-PE-2","vong":"hoc","thuTu":2}'::jsonb, '2026-11-01T13:00:06.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxp8ps801f', 'a1pe07psf050', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"Dans ma famille, nous sommes quatre. Mon père s''appelle Minh, il a cinquante ans et il est médecin. Ma mère a quarante-huit ans et elle est professeure. J''ai aussi une petite sœur. Elle a dix ans."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1pe08psf051', 'practice', 'Écriture A1 : ce que j''aime', 'A1', array['Production écrite']::text[], 'practice', null, null, '<p>Votre ami français vous demande vos goûts.</p><p>Écrivez ce que vous aimez et ce que vous n''aimez pas. Donnez deux exemples de chaque. (30 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• j''aime (expression) : tôi thích\n• je n''aime pas (expression) : tôi không thích\n• je déteste (expression) : tôi ghét\n• aussi (adverbe) : cũng\n• mais (conjonction) : nhưng","explications":"• Sau aimer thường dùng le, la, les: J''aime le café.\n• Phủ định có hai phần: ne… pas.","isPremium":true,"price":19000,"kyNang":"A1-PE-2","vong":"hoc","thuTu":3}'::jsonb, '2026-11-01T13:00:07.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxp8ps801g', 'a1pe08psf051', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"J''aime la musique et le cinéma. Le week-end, je regarde des films avec mes amis. J''aime aussi le café. Mais je n''aime pas le sport et je n''aime pas le thé. Et toi, qu''est-ce que tu aimes ?"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1pe09psf052', 'practice', 'Écriture A1 : ma journée', 'A1', array['Production écrite']::text[], 'practice', null, null, '<p>Racontez une journée normale.</p><p>Écrivez au moins trois activités et donnez l''heure. (35 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• je me lève (expression) : tôi thức dậy\n• je mange (expression) : tôi ăn\n• je vais à (expression) : tôi đi đến\n• je rentre (expression) : tôi về\n• le matin, le soir (expression) : buổi sáng, buổi tối","explications":"• Nói việc hằng ngày dùng thì hiện tại.\n• Mở câu bằng thời gian: Le matin, À midi, Le soir.","isPremium":true,"price":19000,"kyNang":"A1-PE-2","vong":"hoc","thuTu":4}'::jsonb, '2026-11-01T13:00:08.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxp8ps801h', 'a1pe09psf052', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"Le matin, je me lève à sept heures et je prends un café. Je vais à l''université à huit heures. À midi, je mange avec mes amis. Le soir, je rentre à la maison à six heures et je regarde un film."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1pe10psf053', 'practice', 'Écriture A1 : ma ville', 'A1', array['Production écrite']::text[], 'practice', null, null, '<p>Décrivez votre ville et votre maison ou votre appartement.</p><p>Dites où vous habitez et ce qu''il y a dans votre ville. (35 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• il y a (expression) : có\n• une ville (nom féminin) : thành phố\n• beau, belle (adjectif) : đẹp\n• une rivière (nom féminin) : con sông\n• une chambre (nom féminin) : phòng ngủ","explications":"• Il y a là từ quan trọng nhất khi mô tả nơi chốn.\n• Tính từ đổi theo giống: un petit appartement, une petite maison.","isPremium":true,"price":19000,"kyNang":"A1-PE-2","vong":"on","thuTu":5}'::jsonb, '2026-11-01T13:00:09.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxp8ps801i', 'a1pe10psf053', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"J''habite à Hué, au Vietnam. C''est une belle ville. Il y a une grande rivière, des restaurants et beaucoup de cafés. Mon appartement est petit mais il est joli. Il y a deux chambres et une cuisine."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1pe11psf054', 'practice', 'Écriture A1 : mon ami', 'A1', array['Production écrite']::text[], 'practice', null, null, '<p>Écrivez un petit texte sur un ami ou une amie.</p><p>Donnez son nom, son âge, sa ville, et dites ce qu''il ou elle aime. (40 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• mon ami, mon amie (expression) : bạn tôi\n• il s''appelle, elle s''appelle (expression) : anh ấy, chị ấy tên là\n• gentil, gentille (adjectif) : tốt bụng\n• un voyage (nom masculin) : chuyến đi\n• très (adverbe) : rất","explications":"• Bài này phải đổi ngôi: j''habite thành il habite, elle habite.\n• Viết xong rà riêng động từ: mọi động từ đã chia theo il hoặc elle chưa.","isPremium":true,"price":19000,"kyNang":"A1-PE-2","vong":"chot","thuTu":6}'::jsonb, '2026-11-01T13:00:10.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxp8ps801j', 'a1pe11psf054', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"Mon amie s''appelle Sophie. Elle a vingt-cinq ans et elle est française. Elle habite à Nantes avec sa sœur. Elle est infirmière dans un hôpital. Elle aime la danse et les voyages, mais elle n''aime pas le froid. Elle est très gentille."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1pe12psg055', 'practice', 'Écriture A1 : je t''invite', 'A1', array['Production écrite']::text[], 'practice', null, null, '<p>C''est votre anniversaire samedi. Vous écrivez à votre ami Thomas.</p><p>Vous l''invitez. Vous donnez le jour, l''heure et le lieu. (40 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• je t''invite (expression) : mình mời bạn\n• chez moi (expression) : ở nhà mình\n• tu viens ? (expression) : bạn đến chứ?\n• réponds-moi (expression) : trả lời mình nhé\n• à bientôt (expression) : hẹn sớm gặp lại","explications":"• Thư có ba phần: lời chào, nội dung, lời kết.\n• Gạch từng ý đề yêu cầu: ngày, giờ, nơi.","kyNang":"A1-PE-3","vong":"hoc","thuTu":1}'::jsonb, '2026-11-01T13:00:11.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxp8ps801k', 'a1pe12psg055', 1, 'open', 'Écrivez votre message.', '{}'::jsonb, '{"model":"Salut Thomas ! Samedi, c''est mon anniversaire. Je t''invite chez moi à dix-neuf heures. J''habite 8, rue de la Paix. Il y a aussi Léa et Hugo. Nous allons manger un gâteau et écouter de la musique. Tu viens ? Réponds-moi vite ! À bientôt, Lan"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1pe13psg056', 'practice', 'Écriture A1 : ce week-end', 'A1', array['Production écrite']::text[], 'practice', null, null, '<p>Vous écrivez à votre amie Emma.</p><p>Vous lui dites ce que vous faites ce week-end : samedi et dimanche. Vous lui posez une question. (40 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• ce week-end (expression) : cuối tuần này\n• rester (verbe) : ở lại\n• visiter (verbe) : tham quan\n• un marché (nom masculin) : chợ\n• et toi ? (expression) : còn bạn?","explications":"• Ở A1 có thể dùng hiện tại để nói việc sắp làm.\n• Đừng quên câu hỏi cuối thư: đó là một ý đề yêu cầu.","kyNang":"A1-PE-3","vong":"hoc","thuTu":2}'::jsonb, '2026-11-01T13:00:12.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxp8ps801l', 'a1pe13psg056', 1, 'open', 'Écrivez votre message.', '{}'::jsonb, '{"model":"Salut Emma ! Ce week-end, je reste à Paris. Samedi matin, je vais au marché avec ma sœur. L''après-midi, nous visitons un musée. Dimanche, je reste à la maison et je travaille un peu. Et toi, qu''est-ce que tu fais ce week-end ? Bises, Mai"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1pe14psg057', 'practice', 'Écriture A1 : une carte de vacances', 'A1', array['Production écrite']::text[], 'practice', null, null, '<p>Vous êtes en vacances. Vous écrivez une carte postale à votre ami Lucas.</p><p>Vous dites où vous êtes, quel temps il fait et ce que vous faites. (40 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une carte postale (expression) : bưu thiếp\n• il fait beau (expression) : trời đẹp\n• il fait chaud (expression) : trời nóng\n• il pleut (expression) : trời mưa\n• grosses bises (expression) : thân mến, cách kết thư","explications":"• Thời tiết dùng il fait: il fait beau, il fait froid.\n• Cher đi với nam, chère đi với nữ.","isPremium":true,"price":19000,"kyNang":"A1-PE-3","vong":"hoc","thuTu":3}'::jsonb, '2026-11-01T13:00:13.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxp8ps801m', 'a1pe14psg057', 1, 'open', 'Écrivez votre carte.', '{}'::jsonb, '{"model":"Cher Lucas, je suis à Nice avec ma famille. Il fait beau et chaud. Le matin, je vais à la plage. L''après-midi, nous visitons la ville et nous mangeons des glaces. L''hôtel est très joli. Je rentre lundi. Grosses bises, Mai"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1pe15psg058', 'practice', 'Écriture A1 : je réponds à Julie', 'A1', array['Production écrite']::text[], 'practice', null, null, '<p>Vous lisez le message de Julie. Vous lui répondez.</p><p>Vous répondez à ses deux questions. (40 mots minimum)</p>', '<p>Salut ! Je viens dans ta ville en juin. Qu''est-ce qu''on peut visiter ? Et où est-ce qu''on mange bien ? Julie</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• super ! (interjection) : tuyệt!\n• tu peux (expression) : bạn có thể\n• visiter (verbe) : tham quan\n• je connais (expression) : mình biết\n• près de (expression) : gần","explications":"• Thư có hai câu hỏi thì phải trả lời đủ cả hai.\n• Viết hay mà sót ý vẫn mất điểm bám đề.","isPremium":true,"price":19000,"kyNang":"A1-PE-3","vong":"hoc","thuTu":4}'::jsonb, '2026-11-01T13:00:14.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxp8ps801n', 'a1pe15psg058', 1, 'open', 'Écrivez votre réponse.', '{}'::jsonb, '{"model":"Salut Julie ! Super, tu viens en juin ! Dans ma ville, tu peux visiter le vieux quartier et le musée. Il y a aussi un grand parc. Pour manger, je connais un petit restaurant près de chez moi. C''est très bon. À bientôt, Nam"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1pe16psh059', 'practice', 'Écriture A1 : un petit service', 'A1', array['Production écrite']::text[], 'practice', null, null, '<p>Vous partez une semaine. Vous écrivez à votre voisin, Monsieur Blanc.</p><p>Vous lui demandez de s''occuper de vos plantes. Vous dites quand vous partez et où est la clé. (40 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• pouvez-vous… ? (expression) : ông, bà có thể… không?\n• une plante (nom féminin) : cây cảnh\n• l''eau (nom féminin) : nước\n• s''il vous plaît (expression) : làm ơn\n• une gardienne (nom féminin) : bà quản lý toà nhà","explications":"• Viết cho hàng xóm dùng vous, chào bằng Bonjour Monsieur.\n• Viết cho bạn dùng tu, chào bằng Salut.","isPremium":true,"price":19000,"kyNang":"A1-PE-3","vong":"on","thuTu":5}'::jsonb, '2026-11-01T13:00:15.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxp8ps801o', 'a1pe16psh059', 1, 'open', 'Écrivez votre message.', '{}'::jsonb, '{"model":"Bonjour Monsieur Blanc, je pars à Lyon lundi pour une semaine. Pouvez-vous donner de l''eau à mes plantes, s''il vous plaît ? La clé est chez la gardienne. Je rentre dimanche prochain. Merci beaucoup pour votre aide ! Bonne journée, Madame Tran"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1pe17psh05a', 'practice', 'Écriture A1 : écrivez à votre ami', 'A1', array['Production écrite']::text[], 'practice', null, null, '<p>Vous êtes en France. Vous écrivez à votre ami Marc.</p><p>Vous lui parlez de votre nouvelle ville et de votre école. Vous l''invitez à venir chez vous. (40 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• nouveau, nouvelle (adjectif) : mới\n• depuis (préposition) : từ, đã được\n• un mois (nom masculin) : tháng\n• tu veux… ? (expression) : bạn muốn… không?\n• ensemble (adverbe) : cùng nhau","explications":"• Bài thi cần từ 40 từ: nhìn bộ đếm bên dưới khung viết.\n• Trước khi nộp, đánh dấu đủ từng ý của đề.","isPremium":true,"price":19000,"kyNang":"A1-PE-3","vong":"chot","thuTu":6}'::jsonb, '2026-11-01T13:00:16.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxp8ps801p', 'a1pe17psh05a', 1, 'open', 'Écrivez votre message.', '{}'::jsonb, '{"model":"Salut Marc ! Je suis à Rennes depuis un mois. C''est une petite ville très jolie. Mon école est près de la gare et mes professeurs sont gentils. Tu veux venir chez moi en mai ? Nous pouvons visiter la ville ensemble. À bientôt, Linh"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1pe18psh05b', 'practice', 'Écriture A1 : un, une, des', 'A1', array['Production écrite']::text[], 'practice', null, null, '<p>Complétez avec un, une ou des.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un (article) : mạo từ giống đực số ít\n• une (article) : mạo từ giống cái số ít\n• des (article) : mạo từ số nhiều\n• un livre (nom masculin) : quyển sách\n• une pomme (nom féminin) : quả táo","explications":"• Học từ mới luôn kèm mạo từ: une table, un livre.\n• Số nhiều thường thêm -s, nhìn đuôi từ để chọn des.","isPremium":true,"price":19000,"kyNang":"A1-PE-4","vong":"hoc","thuTu":3}'::jsonb, '2026-11-01T13:00:17.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxp8ps801q', 'a1pe18psh05b', 1, 'fill', 'C''est ______ livre.', '{}'::jsonb, '{"accepted":"un"}'::jsonb, 'livre là giống đực, số ít.'), ('qmvxp8ps801r', 'a1pe18psh05b', 2, 'fill', 'C''est ______ table.', '{}'::jsonb, '{"accepted":"une"}'::jsonb, 'table là giống cái, số ít.'), ('qmvxp8ps801s', 'a1pe18psh05b', 3, 'fill', 'Ce sont ______ stylos.', '{}'::jsonb, '{"accepted":"des"}'::jsonb, 'stylos là số nhiều.'), ('qmvxp8ps801t', 'a1pe18psh05b', 4, 'fill', 'J''ai ______ sœur.', '{}'::jsonb, '{"accepted":"une"}'::jsonb, 'sœur là giống cái.'), ('qmvxp8ps801u', 'a1pe18psh05b', 5, 'fill', 'Il y a ______ enfants dans le parc.', '{}'::jsonb, '{"accepted":"des"}'::jsonb, 'enfants là số nhiều.'), ('qmvxp8ps801v', 'a1pe18psh05b', 6, 'fill', 'Elle a ______ chat.', '{}'::jsonb, '{"accepted":"un"}'::jsonb, 'chat là giống đực.'), ('qmvxp8ps801w', 'a1pe18psh05b', 7, 'fill', 'Je mange ______ pomme.', '{}'::jsonb, '{"accepted":"une"}'::jsonb, 'pomme là giống cái.'), ('qmvxp8ps801